/**
 * SHA-256 of a UTF-8 string, as the eight 32-bit words of the digest.
 *
 * Rolled rather than unrolled: this hashes a public key, well under a kilobyte
 * and once per process, so the size of the code matters and its throughput does
 * not.
 *
 * Correctness is pinned by `sha256EncodeSync.test.ts` against digests generated
 * with `node:crypto`, covering every padding and multi-block boundary.
 */
export declare function sha256(message: string): number[];
